sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_estado": "v_estado",
       "v_tipo_de_ranking": "v_tipo_de_ranking",
       "v_posicao": "v_posicao",
       "v_porcentagem": "v_porcentagem",
       "v_ano": "v_ano"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');
       if (fieldMapping[questionName]) {
            fieldMapping[questionName] = value;
       }
   }

outputs.v_estado = fieldMapping['v_estado'];
outputs.v_tipo_de_ranking = fieldMapping['v_tipo_de_ranking'];
outputs.v_posicao = fieldMapping['v_posicao'];
outputs.v_porcentagem = fieldMapping['v_porcentagem'];
outputs.v_ano = fieldMapping['v_ano'];

})(inputs, outputs);

